test('volcanic asset uses real Wild Engine instances, authored fluid and the confirmed clock',async()=>{
 const oldFetch=globalThis.fetch,oldBitmap=globalThis.createImageBitmap,manifest=JSON.parse(readFileSync('public/content/biome-volcanoes.json','utf8')),binary=readFileSync('public'+manifest.binary.url),requests=[];globalThis.fetch=async url=>{requests.push(String(url));return {ok:true,json:async()=>manifest,arrayBuffer:async()=>binary.buffer.slice(binary.byteOffset,binary.byteOffset+binary.byteLength),blob:async()=>new Blob(['x'])};};globalThis.createImageBitmap=async()=>({close(){}});
 const clock=createConfirmedPresentationClock(0);try{const biomePack=await loadWebGpuBiomePack('volcanes');const core=createSpatialWorld(new WebAssembly.Module(readFileSync('src/world/wild-engine/spatial-savanna.wasm')));core.generate(28,0,0,'volcanoes');core.addChunk(-4,-4);const payload=core.chunkPayload();assert.ok(payload.instances[19].length);const scene=new Scene(),state={biome:'volcanes',seed:'28',elapsed:0,suppressed:[]},props=createWebGpuBiomeProps({scene,state,confirmedClock:clock,biomePack,initialSlots:[19]});props.replace(payload,1);assert.equal(await props.ready,true);const solid=scene.children.find(mesh=>!mesh.userData.nativeFluid),lava=scene.children.find(mesh=>mesh.userData.nativeFluid==='asset');assert.equal(solid.count,payload.instances[19].length);assert.equal(lava.count,solid.count);assert.equal(lava.geometry.attributes.position.count,manifest.assets[19].water.outline.length*3);assert.ok(lava.material.colorNode?.isNode);assert.equal(lava.material.opacityNode,solid.material.opacityNode);const terrainLava=createWebGpuLavaMaterial({color:biomePack.profile.colors.water,seed:lavaWorldSeed(state.seed),clockNode:clock.node,clip:false});assert.equal(terrainLava.colorNode,lava.material.colorNode);terrainLava.dispose();clock.commit(2);assert.equal(clock.node.value,2);assert.equal(requests.filter(url=>url.includes('biome-volcanoes.json')).length,1);props.dispose();}finally{clock.dispose();globalThis.fetch=oldFetch;globalThis.createImageBitmap=oldBitmap;}
});

test('biome instances borrow the surface-owned water material',async()=>{
 const oldFetch=globalThis.fetch,oldBitmap=globalThis.createImageBitmap,{buffer,manifest}=pack();manifest.assets[19]={...manifest.assets[19],water:{level:0,outline:[[0,0],[1,0],[0,1]]}};globalThis.fetch=async()=>({ok:true,json:async()=>manifest,arrayBuffer:async()=>buffer,blob:async()=>new Blob(['x'])});globalThis.createImageBitmap=async()=>({close(){}});const fluidMaterial=new (await import('three')).MeshBasicMaterial();let disposed=0;fluidMaterial.addEventListener('dispose',()=>disposed++);
 try{const scene=new Scene(),props=createWebGpuBiomeProps({scene,state:{biome:'sabana',suppressed:[]},fluidMaterial,initialSlots:[19]}),instances=Array.from({length:20},()=>[]);instances[19].push({id:'pond',slot:19,x:0,y:0,z:0,yaw:0,sx:1,sy:1,sz:1});props.replace({cx:0,cz:0,instances},1);assert.equal(await props.ready,true);assert.equal(scene.children.find(mesh=>mesh.userData.nativeFluid==='asset').material,fluidMaterial);props.dispose();assert.equal(disposed,0);}finally{fluidMaterial.dispose();globalThis.fetch=oldFetch;globalThis.createImageBitmap=oldBitmap;}
});
